arguments.command:
node -e '
const fs = require("fs");
const https = require("https");
const options = {
  hostname: "en.wikipedia.org",
  path: "/wiki/Eileen_Gu",
  method: "GET",
  headers: { "User-Agent": "Mozilla/5.0" }
};
https.get(options, (res) => {
  let data = "";
  res.on("data", (chunk) => data += chunk);
  res.on("end", () => {
    fs.writeFileSync("gu.html", data);
    console.log("Downloaded gu.html");
  });
});
'

